import os
import sqlite3
import sys

BASE_DIR = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
DB_PATH = os.path.join(BASE_DIR, "stock.db")
LOCK_WAIT_SECONDS = 5.0


def usage():
    print("usage: reserve.py REQUEST_ID POSITIVE_QUANTITY", file=sys.stderr)
    return 2


def reserve(request_id, quantity):
    db = sqlite3.connect(
        DB_PATH,
        timeout=LOCK_WAIT_SECONDS,
        isolation_level=None,
    )
    try:
        db.execute("PRAGMA busy_timeout = %d" % (LOCK_WAIT_SECONDS * 1000))
        db.execute("BEGIN IMMEDIATE")

        existing = db.execute(
            "SELECT quantity FROM reservations WHERE request_id = ?",
            (request_id,),
        ).fetchone()
        if existing is not None:
            db.execute("COMMIT")
            print("reserved request_id=%s quantity=%d" % (request_id, existing[0]))
            return 0

        changed = db.execute(
            "UPDATE stock SET remaining = remaining - ? "
            "WHERE id = 1 AND remaining >= ?",
            (quantity, quantity),
        )
        if changed.rowcount != 1:
            stock = db.execute(
                "SELECT remaining FROM stock WHERE id = 1"
            ).fetchone()
            db.execute("ROLLBACK")
            if stock is None:
                print("error: stock row 1 is missing", file=sys.stderr)
                return 1
            print(
                "insufficient stock: requested=%d remaining=%d"
                % (quantity, stock[0]),
                file=sys.stderr,
            )
            return 1

        db.execute(
            "INSERT INTO reservations (request_id, quantity) VALUES (?, ?)",
            (request_id, quantity),
        )
        remaining = db.execute(
            "SELECT remaining FROM stock WHERE id = 1"
        ).fetchone()[0]
        db.execute("COMMIT")
        print(
            "reserved request_id=%s quantity=%d remaining=%d"
            % (request_id, quantity, remaining)
        )
        return 0
    except sqlite3.OperationalError as exc:
        if db.in_transaction:
            db.execute("ROLLBACK")
        if "locked" in str(exc).lower() or "busy" in str(exc).lower():
            print(
                "temporary failure: database remained locked for %.1f seconds"
                % LOCK_WAIT_SECONDS,
                file=sys.stderr,
            )
            return 75
        print("database error: %s" % exc, file=sys.stderr)
        return 1
    except sqlite3.DatabaseError as exc:
        if db.in_transaction:
            db.execute("ROLLBACK")
        print("database error: %s" % exc, file=sys.stderr)
        return 1
    finally:
        db.close()


def main(argv):
    if len(argv) != 3 or not argv[1]:
        return usage()
    try:
        quantity = int(argv[2])
    except ValueError:
        return usage()
    if quantity <= 0:
        print("quantity must be a positive integer", file=sys.stderr)
        return 2
    return reserve(argv[1], quantity)


if __name__ == "__main__":
    sys.exit(main(sys.argv))
